import{_ as n,o as h,c as o,a3 as g}from"./chunks/framework.MGD2uYU7.js";const l=JSON.parse('{"title":"01 — Tài liệu Yêu cầu Nghiệp vụ (BRD)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/01-brd.md","filePath":"guide/01-brd.md","lastUpdated":null}'),r={name:"guide/01-brd.md"};function c(d,t,i,s,e,a){return h(),o("div",null,[...t[0]||(t[0]=[g('<h1 id="_01-—-tai-lieu-yeu-cau-nghiep-vu-brd" tabindex="-1">01 — Tài liệu Yêu cầu Nghiệp vụ (BRD) <a class="header-anchor" href="#_01-—-tai-lieu-yeu-cau-nghiep-vu-brd" aria-label="Permalink to &quot;01 — Tài liệu Yêu cầu Nghiệp vụ (BRD)&quot;">​</a></h1><p><strong>Dự án</strong>: Hệ thống phần mềm &amp; website cho Chủ đầu tư <strong>An Phúc</strong> — dự án <strong>An Phúc Imperia</strong><strong>Status</strong>: Draft gửi khách hàng rà soát — <strong>Updated</strong>: 2026-10-12 — <strong>Version</strong>: 2.1 (cập nhật theo cột <em>Comment An Phúc</em>: phân quyền ✅, luồng lead 9 trường ✅, thêm BR‑17/BR‑18, rủi ro R7) <strong>Đơn vị yêu cầu</strong>: MAYogu × CTCP Phát triển nhà ở xã hội An Phúc (CĐT — &quot;AP&quot;) <strong>Nguồn chuẩn</strong>: Google Sheet 7 tab <em>&quot;PHẦN MỀM TỔNG – HỆ THỐNG QUẢN LÝ KHÁCH HÀNG &amp; HỒ SƠ&quot;</em>.</p><blockquote><p>BRD này <strong>chỉ tổng hợp và hệ thống hoá những gì sheet nêu</strong>. Không thêm mục tiêu/KPI/tính năng ngoài sheet. Phần chưa rõ đánh dấu 🟡, đề xuất chưa duyệt đánh dấu 🔵; tất cả đẩy về <code>docs/09</code>. Nguyên tắc trung thực đầy đủ ở <code>docs/00</code> §2.</p></blockquote><hr><h2 id="_1-boi-canh-bai-toan-kinh-doanh" tabindex="-1">1. Bối cảnh &amp; bài toán kinh doanh <a class="header-anchor" href="#_1-boi-canh-bai-toan-kinh-doanh" aria-label="Permalink to &quot;1. Bối cảnh &amp; bài toán kinh doanh&quot;">​</a></h2><p><strong>Chủ đầu tư An Phúc (AP)</strong> triển khai dự án <strong>An Phúc Imperia</strong> (Khu nhà ở xã hội tại ô A2‑OXH2, QH phân khu số 9, phường Từ Sơn, Bắc Ninh — QĐ 856/QĐ‑UBND 22/06/2026), gồm <strong>04 toà NOXH 23 tầng (~1.600 căn, 05 mẫu căn A1–A5)</strong> và <strong>01 toà nhà ở thương mại 24 tầng + 2 hầm (~440 căn — 08 mẫu căn TM1–TM8 theo sheet bổ sung 10/2026)</strong>.</p><p>AP bán <strong>sơ cấp</strong> (trực tiếp từ CĐT) cả hai dòng sản phẩm <strong>NOXH</strong> và <strong>NOTM</strong>. Việc tiếp cận khách hàng và xử lý hồ sơ diễn ra qua <strong>nhiều kênh rời rạc</strong>: website giới thiệu dự án, website tiếp nhận hồ sơ NOXH, website bán NOTM, các điểm truyền thông trực tiếp (biển bảng, ấn phẩm), và kênh truyền thông online (web tổng, Facebook, quảng cáo).</p><p><strong>Bài toán (nguyên văn mô hình Sheet 01):</strong> dữ liệu khách từ <strong>5 nguồn</strong> đang phân tán; AP cần <strong>một nơi lưu trữ trung tâm</strong> để <em>&quot;theo dõi khách hàng, lịch sử trao đổi, tiến trình xử lý hồ sơ; lưu bản scan hồ sơ/tài liệu theo ID khách hàng&quot;</em> — mỗi khách <strong>một ID duy nhất</strong> — đồng thời <strong>liên kết phần mềm kế toán</strong> để cập nhật trạng thái/số tiền thanh toán và xuất hoá đơn điện tử.</p><p><strong>Riêng NOXH</strong>, quy trình tiếp nhận &amp; xét duyệt hồ sơ chịu ràng buộc pháp lý chặt (Luật Nhà ở 2023, NĐ 13/2023…), trải qua <strong>20 bước</strong> từ đăng ký đến bàn giao, có sự tham gia của <strong>Sở Xây dựng</strong> và yêu cầu <strong>minh bạch phục vụ thanh kiểm tra</strong> (bốc thăm lưu vết, chọn căn theo thứ tự công khai, báo cáo định kỳ cho Sở).</p><hr><h2 id="_2-muc-tieu-nghiep-vu-rut-truc-tiep-tu-sheet-—-khong-đat-kpi-so-khi-sheet-chua-neu" tabindex="-1">2. Mục tiêu nghiệp vụ (rút trực tiếp từ sheet — không đặt KPI số khi sheet chưa nêu) <a class="header-anchor" href="#_2-muc-tieu-nghiep-vu-rut-truc-tiep-tu-sheet-—-khong-đat-kpi-so-khi-sheet-chua-neu" aria-label="Permalink to &quot;2. Mục tiêu nghiệp vụ (rút trực tiếp từ sheet — không đặt KPI số khi sheet chưa nêu)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Mục tiêu</th><th>Nguồn sheet</th><th>Đo lường</th></tr></thead><tbody><tr><td>G1</td><td><strong>Gom dữ liệu 5 nguồn về 1 kho trung tâm</strong>, mỗi khách <strong>1 ID duy nhất</strong></td><td>Sheet 01</td><td>Định tính ✅ — sheet không nêu KPI số (🟡 OQ‑B1)</td></tr><tr><td>G2</td><td><strong>Theo dõi toàn trình</strong>: lịch sử trao đổi, tiến trình xử lý hồ sơ, tiến trình thanh toán (ký HĐ → bàn giao), lưu bản scan theo ID</td><td>Sheet 01 (5 chức năng trung tâm)</td><td>Mọi tương tác/thay đổi trạng thái <strong>ghi thời gian + tài khoản thao tác</strong> ✅</td></tr><tr><td>G3</td><td><strong>Chuẩn hoá &amp; xuất biểu mẫu nhanh</strong>: <em>&quot;chọn biểu mẫu và xuất ra ngay, không cần tự soạn thảo&quot;</em>; ADMIN tự thêm mẫu</td><td>Sheet 01 (ghi chú)</td><td>Định tính ✅ (tờ trình/báo cáo Sở, hợp đồng, giấy xác nhận…)</td></tr><tr><td>G4</td><td><strong>Số hoá quy trình NOXH 20 bước</strong> minh bạch, đúng luật, phục vụ thanh kiểm tra</td><td>Sheet 03</td><td>Định tính ✅ (bốc thăm lưu vết, chọn căn công khai theo thứ tự)</td></tr><tr><td>G5</td><td><strong>Hỗ trợ bán NOTM</strong> theo quy trình 8 bước (đăng ký → tư vấn → chốt căn → ký HĐ → thanh toán → bàn giao)</td><td>Sheet 04</td><td>Định tính ✅</td></tr><tr><td>G6</td><td><strong>Giới thiệu doanh nghiệp/dự án</strong> trên Web CĐT (bố cục theo template FIND), thu lead</td><td>Sheet 02</td><td>Định tính ✅</td></tr><tr><td>G7</td><td><strong>Điều phối lead online</strong> (web, Facebook, quảng cáo) về CRM, chuẩn hoá nguồn/campaign</td><td>Sheet 07 (06_TT_ONLINE)</td><td>Định tính ✅</td></tr><tr><td>G8</td><td><strong>Chuẩn hoá ấn phẩm truyền thông trực tiếp</strong> (12 hạng mục biển bảng/in ấn)</td><td>Sheet 06 (05_TT_TRUC_TIEP)</td><td>Định tính ✅ (không phải phần mềm)</td></tr><tr><td>G9</td><td><strong>Tuân thủ pháp lý</strong>: NĐ 13/2023, đăng ký TMĐT, Luật KDBĐS/Nhà ở 2023, DPA, AI on‑prem VN, ATTT</td><td>Sheet 05 (LEGAL)</td><td>Định tính ✅ — ràng buộc bắt buộc</td></tr><tr><td>G10</td><td><strong>Liên kết kế toán</strong> để tự động cập nhật thanh toán + xuất hoá đơn điện tử</td><td>Sheet 01 (bổ sung)</td><td>🟡 cơ chế/tên phần mềm chưa nêu (OQ‑C1)</td></tr></tbody></table><blockquote><p>⚠️ Sheet <strong>không</strong> đặt chỉ tiêu doanh số, GMV, tỉ lệ chuyển đổi, số lead… → <strong>không tự đặt</strong>. Nếu AP muốn có KPI số, bổ sung ở <code>docs/09</code> (OQ‑B1).</p></blockquote><hr><h2 id="_3-pham-vi-7-mang-a–g" tabindex="-1">3. Phạm vi (7 mảng A–G) <a class="header-anchor" href="#_3-pham-vi-7-mang-a–g" aria-label="Permalink to &quot;3. Phạm vi (7 mảng A–G)&quot;">​</a></h2><p>Chi tiết từng mảng ở doc tương ứng (<code>docs/02</code>–<code>docs/08</code>). Bảng dưới là khung phạm vi cấp dự án.</p><table tabindex="0"><thead><tr><th>Mảng</th><th>Tên</th><th>Bản chất</th><th>Doc</th><th>Trong phạm vi phần mềm?</th></tr></thead><tbody><tr><td><strong>A</strong></td><td>Phần mềm tổng / CRM</td><td>Back‑office trung tâm: 5 chức năng + kho biểu mẫu + nối kế toán</td><td><code>02</code></td><td>✅ Có</td></tr><tr><td><strong>B</strong></td><td>Web Chủ đầu tư</td><td>Website marketing dự án (sửa từ template FIND), thu lead</td><td><code>03</code></td><td>✅ Có</td></tr><tr><td><strong>C</strong></td><td>Web Nhà ở xã hội (NOXH)</td><td>Web/app nghiệp vụ: tiếp nhận &amp; xử lý hồ sơ <strong>20 bước</strong> + phân quyền + state machine</td><td><code>04</code></td><td>✅ Có</td></tr><tr><td><strong>D</strong></td><td>Web Nhà ở thương mại (NOTM)</td><td>Web nghiệp vụ: bán hàng <strong>8 bước</strong></td><td><code>05</code></td><td>✅ Có</td></tr><tr><td><strong>E</strong></td><td>Legal</td><td>Ràng buộc pháp lý &amp; tuân thủ (9 mục), phân định AP ↔ MAYogu</td><td><code>06</code></td><td>⚖️ Ràng buộc (không phải module)</td></tr><tr><td><strong>F</strong></td><td>Truyền thông trực tiếp</td><td><strong>12 hạng mục ấn phẩm</strong> in/biển bảng vật lý</td><td><code>07</code></td><td>❌ Không (thiết kế/in ấn)</td></tr><tr><td><strong>G</strong></td><td>Truyền thông online</td><td>Thiết lập kênh + quy trình <strong>đổ lead về CRM</strong></td><td><code>08</code></td><td>🔗 Một phần (tích hợp lead)</td></tr></tbody></table><p><strong>Ranh giới rõ ràng:</strong></p><ul><li><strong>Sản phẩm phần mềm/website</strong> = <strong>A, B, C, D</strong>.</li><li><strong>E</strong> = ràng buộc tuân thủ áp lên toàn bộ (đặc biệt A, C, D).</li><li><strong>F</strong> = hạng mục <strong>thiết kế đồ hoạ &amp; in ấn vật lý</strong> — tài liệu mô tả đúng bản chất, <strong>không &quot;phần mềm hoá&quot;</strong> (không biến biển bảng thành màn hình).</li><li><strong>G</strong> = <strong>thiết lập kênh online + tích hợp lead về CRM</strong>; phần &quot;nội dung/quảng cáo&quot; là nghiệp vụ marketing, phần &quot;đổ lead về CRM&quot; mới là tích hợp phần mềm.</li></ul><hr><h2 id="_4-vai-tro-cac-ben-lien-quan-stakeholders" tabindex="-1">4. Vai trò &amp; các bên liên quan (stakeholders) <a class="header-anchor" href="#_4-vai-tro-cac-ben-lien-quan-stakeholders" aria-label="Permalink to &quot;4. Vai trò &amp; các bên liên quan (stakeholders)&quot;">​</a></h2><h3 id="_4-1-vai-tro-van-hanh-he-thong-nguon-sheet-03-phan-quyen-—-✅-ap-đa-chot-3-nhom-quyen-cđt-2026‐10" tabindex="-1">4.1 Vai trò vận hành hệ thống (nguồn Sheet 03 &quot;PHÂN QUYỀN&quot; — ✅ AP đã chốt 3 nhóm quyền CĐT, 2026‑10) <a class="header-anchor" href="#_4-1-vai-tro-van-hanh-he-thong-nguon-sheet-03-phan-quyen-—-✅-ap-đa-chot-3-nhom-quyen-cđt-2026‐10" aria-label="Permalink to &quot;4.1 Vai trò vận hành hệ thống (nguồn Sheet 03 &quot;PHÂN QUYỀN&quot; — ✅ AP đã chốt 3 nhóm quyền CĐT, 2026‑10)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mã</th><th>Vai trò</th><th>Phạm vi quyền (nguyên văn sheet + ✅ Comment An Phúc)</th></tr></thead><tbody><tr><td><code>ADMIN</code></td><td>Nhân sự quản trị web của CĐT</td><td>Toàn quyền chỉnh sửa nội dung hiển thị, cập nhật trạng thái hồ sơ; <strong>không</strong> sửa cấu trúc web. ✅ AP: toàn quyền <strong>trừ code (thuộc IT)</strong>; nhân sự phụ trách chính website; <strong>duyệt sau cùng</strong> đề nghị đổi trạng thái; phân công lead/hồ sơ cho sale</td></tr><tr><td><code>STAFF</code></td><td>Nhân viên kinh doanh / soát hồ sơ</td><td>Xem và cập nhật trạng thái hồ sơ <strong>được chỉ định</strong>. ✅ AP: nhân sự check hồ sơ <strong>xem + ĐỀ NGHỊ đổi trạng thái</strong> (từ chối/cần bổ sung/duyệt online) → <strong>ADMIN duyệt sau cùng</strong></td></tr><tr><td><code>CUSTOMER</code></td><td>Khách hàng</td><td><strong>Chỉ</strong> xem và sửa hồ sơ <strong>của chính mình</strong></td></tr><tr><td><code>DOC</code></td><td>Sở Xây dựng</td><td>✅ <strong>AP đã chốt (OQ‑6/OQ‑R1)</strong>: <em>&quot;có quyền xem, theo dõi, giám sát, không có quyền thay đổi hay bất kì thao tác nào khác làm thay đổi thông tin/trạng thái hồ sơ&quot;</em> → <strong>read‑only</strong></td></tr><tr><td><code>ACCOUNTANT</code></td><td>Kế toán của CĐT</td><td>Chỉ xem tình trạng thanh toán + thông tin cá nhân khách <strong>để xuất hoá đơn</strong></td></tr></tbody></table><h3 id="_4-2-cac-ben-lien-quan-cap-du-an" tabindex="-1">4.2 Các bên liên quan cấp dự án <a class="header-anchor" href="#_4-2-cac-ben-lien-quan-cap-du-an" aria-label="Permalink to &quot;4.2 Các bên liên quan cấp dự án&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bên</th><th>Vai trò trong dự án</th><th>Trách nhiệm chính (Sheet 05)</th></tr></thead><tbody><tr><td><strong>AP (CĐT An Phúc)</strong></td><td>Chủ đầu tư, sở hữu dữ liệu, đứng tên pháp lý</td><td>Chịu trách nhiệm pháp lý <strong>chính</strong>: DPIA, đăng ký TMĐT, nội dung công bố, DPA, chọn+chi trả hạ tầng AI tại VN</td></tr><tr><td><strong>MAYogu</strong></td><td>Đơn vị phát triển phần mềm/website</td><td>Trách nhiệm <strong>kỹ thuật</strong>: giải trình bảo mật, lập trình giao diện cam kết/opt‑in, triển khai tích hợp; sau bàn giao chỉ hỗ trợ kỹ thuật</td></tr><tr><td><strong>Sở Xây dựng (<code>DOC</code>)</strong></td><td>Cơ quan phê duyệt danh sách khách đủ điều kiện mua NOXH</td><td>Tiếp nhận tờ trình/báo cáo; phê duyệt (Web NOXH bước 14–15)</td></tr><tr><td><strong>Ngân hàng</strong></td><td>Hỗ trợ vay, bảo lãnh, ký hợp đồng ba bên</td><td>Kết nối bên thứ 3 (Web NOXH bước 19; Sheet 05 mục 9)</td></tr><tr><td><strong>Đơn vị vận chuyển</strong></td><td>🔵 Gửi bản gốc hồ sơ (đề xuất)</td><td>Kết nối bên thứ 3 (Web NOXH bước 12; 🔵 OQ‑P2)</td></tr><tr><td><strong>Đơn vị quảng cáo</strong></td><td>Phối hợp chạy quảng cáo online</td><td>Truyền thông online (Sheet 07 mục 5)</td></tr><tr><td><strong>Luật sư (AP thuê)</strong></td><td>Biên soạn Terms &amp; Privacy &amp; Chính sách</td><td>Sheet 05 mục 5</td></tr></tbody></table><hr><h2 id="_5-non-goals-nhung-gi-khong-nam-trong-yeu-cau-—-đe-tranh-suy-dien" tabindex="-1">5. Non-goals (những gì KHÔNG nằm trong yêu cầu — để tránh suy diễn) <a class="header-anchor" href="#_5-non-goals-nhung-gi-khong-nam-trong-yeu-cau-—-đe-tranh-suy-dien" aria-label="Permalink to &quot;5. Non-goals (những gì KHÔNG nằm trong yêu cầu — để tránh suy diễn)&quot;">​</a></h2><p>Sheet yêu cầu <strong>không</strong> mô tả các nội dung sau. Tài liệu này <strong>không</strong> đưa chúng vào phạm vi:</p><ol><li><strong>KHÔNG phải &quot;sàn mua bán / đấu giá NOXH thứ cấp&quot;.</strong> Không có: đấu giá trực tiếp (live bidding), đặt cọc đấu giá, bước giá, chống trả giá phút chót (anti‑sniping), gói VIP, danh tính ẩn <code>TV-XXXX</code>, đặt lịch xem nhà, chủ nhà tự đăng bán. <em>(Đây là nội dung bộ doc cũ tự suy diễn — đã lưu trữ tại <code>docs/_archive/</code>, không phải yêu cầu của AP.)</em></li><li><strong>KHÔNG tự đặt KPI số</strong> (doanh số, GMV, tỉ lệ chuyển đổi, số lead) — sheet không nêu.</li><li><strong>KHÔNG tự vẽ quy trình đặt cọc/thanh toán/mở bán</strong> khi chưa được AP duyệt (chỉ đạo lặp lại trong Sheet 02).</li><li><strong>KHÔNG tự đặt giá bán, cơ cấu căn, diện tích chính thức</strong> — sheet còn mâu thuẫn/chưa chốt (OQ‑D1, OQ‑N2).</li><li><strong>KHÔNG dùng testimonial giả, slogan/giá trị thương hiệu tự bịa</strong> (Sheet 02 cấm).</li><li><strong>CHƯA bao gồm đặc tả kỹ thuật chi tiết</strong> (API contract, ERD/data dictionary, wireframe từng màn hình, test case, backlog sprint) — <strong>có chủ đích</strong>, lập <strong>sau khi</strong> AP chốt các open question (xem §9 và <code>docs/00</code> §10).</li><li><strong>Không &quot;phần mềm hoá&quot; mảng F</strong> (ấn phẩm vật lý) — chỉ đặc tả thiết kế/in ấn.</li></ol><blockquote><p>Việc rà soát/điều chỉnh <strong>mã nguồn</strong> <code>backend/</code>+<code>frontend/</code> hiện có (đang cài sản phẩm &quot;đấu giá&quot; cũ, không khớp yêu cầu) là <strong>hạng mục riêng</strong>, ngoài phạm vi bộ tài liệu gửi khách lần này.</p></blockquote><hr><h2 id="_6-yeu-cau-nghiep-vu-cap-danh-muc-business-requirements" tabindex="-1">6. Yêu cầu nghiệp vụ cấp danh mục (Business Requirements) <a class="header-anchor" href="#_6-yeu-cau-nghiep-vu-cap-danh-muc-business-requirements" aria-label="Permalink to &quot;6. Yêu cầu nghiệp vụ cấp danh mục (Business Requirements)&quot;">​</a></h2><p>Các quy tắc xuyên suốt, áp cho nhiều mảng (định nghĩa chi tiết trong doc mảng tương ứng):</p><table tabindex="0"><thead><tr><th>ID</th><th>Yêu cầu nghiệp vụ</th><th>Nguồn</th></tr></thead><tbody><tr><td>BR‑01</td><td><strong>Mỗi khách hàng một ID duy nhất</strong>; mọi dữ liệu/lịch sử/scan/thanh toán từ 5 nguồn quy về ID này</td><td>Sheet 01</td></tr><tr><td>BR‑02</td><td><strong>Mọi tương tác &amp; thay đổi trạng thái</strong> đều ghi <strong>thời gian + tài khoản thao tác</strong> (audit trail)</td><td>Sheet 01 (FR-CRM-02/03)</td></tr><tr><td>BR‑03</td><td><strong>Biểu mẫu liên kết dữ liệu khách</strong>: chọn mẫu → xuất ngay (1 khách hoặc danh sách); ADMIN tự thêm mẫu</td><td>Sheet 01 (ghi chú)</td></tr><tr><td>BR‑04</td><td><strong>Tiến trình thanh toán</strong> theo dõi từ ký hợp đồng đến bàn giao (đã trả / còn phải trả / thời hạn), đồng bộ phần mềm kế toán</td><td>Sheet 01 (FR-CRM-04)</td></tr><tr><td>BR‑05</td><td><strong>Hồ sơ NOXH</strong> đi qua state machine chuẩn; <strong>khách bị khóa quyền sửa sau khi nộp</strong>, chỉ mở lại khi &quot;Yêu cầu bổ sung&quot;</td><td>Sheet 03 (bước 9–10)</td></tr><tr><td>BR‑06</td><td><strong>Tiếp nhận hồ sơ theo đợt</strong>: giao diện nộp chỉ mở đúng thời điểm; hạn bổ sung <strong>chung toàn bộ khách</strong>; mốc X / X+5 / X+7 / X+10</td><td>Sheet 03 (bước 4, 10, 14)</td></tr><tr><td>BR‑07</td><td><strong>Trình Sở Xây dựng trong 10 ngày</strong> kể từ ngày kết thúc nhận hồ sơ; chốt hạn nộp bản gốc trước ngày trình Sở 2–3 ngày</td><td>Sheet 03 (bước 14)</td></tr><tr><td>BR‑08</td><td><strong>Bốc thăm</strong> (nếu phát sinh) random <strong>1 lần, lưu vết, truy vết được</strong>, lập biên bản</td><td>Sheet 03 (bước 16)</td></tr><tr><td>BR‑09</td><td><strong>Chọn căn theo thứ tự thời gian hoàn thiện hồ sơ</strong>, công khai thứ tự + khung giờ từng khách, minh bạch phục vụ thanh tra</td><td>Sheet 03 (bước 17)</td></tr><tr><td>BR‑10</td><td><strong>Khách được rút hồ sơ tại mọi bước trước hạn chốt</strong> của đợt</td><td>Sheet 03 (bước 11)</td></tr><tr><td>BR‑11</td><td><strong>Consent opt‑in không tick sẵn, tách bạch mục đích</strong>; giao diện <strong>bắt buộc thao tác</strong> (pop‑up/tick)</td><td>Sheet 05 (mục 1, 5)</td></tr><tr><td>BR‑12</td><td><strong>Dữ liệu khách thuộc sở hữu AP</strong>; MAYogu không trích xuất/mua bán/sử dụng (DPA/NDA)</td><td>Sheet 05 (mục 6)</td></tr><tr><td>BR‑13</td><td>Nếu dùng <strong>AI</strong>: hạ tầng <strong>100% tại Việt Nam</strong> (on‑prem / FPT / Viettel / VNPT), không chuyển dữ liệu ra nước ngoài</td><td>Sheet 05 (mục 7)</td></tr><tr><td>BR‑14</td><td><strong>Đặt cọc ≤ 5% giá bán</strong> nhà ở HTTTL khi đủ điều kiện kinh doanh; cấm huy động vốn trái phép qua app</td><td>Sheet 05 (mục 3)</td></tr><tr><td>BR‑15</td><td><strong>Đăng ký TMĐT (online.gov.vn) trước vận hành</strong>; công khai MST/địa chỉ/đại diện pháp luật/chính sách/tranh chấp/điều khoản</td><td>Sheet 05 (mục 2)</td></tr><tr><td>BR‑16</td><td>Web CĐT <strong>giữ bố cục template FIND</strong>, chỉ thay nội dung/hình ảnh; số &quot;khoảng/dự kiến&quot; <strong>giữ nguyên</strong>, không thành chính thức</td><td>Sheet 02</td></tr><tr><td>BR‑17 🆕</td><td><strong>Luồng lead Web CĐT (✅ AP chốt 2026‑10)</strong>: mọi CTA &quot;ĐĂNG KÝ NHẬN THÔNG TIN&quot; → <strong>1 form duy nhất 9 trường</strong> (họ tên, SĐT, email, sản phẩm NOXH/NOTM, loại căn, hôn nhân, đối tượng chính sách 1‑of‑11, nhà ở 1‑of‑3, thu nhập 1‑of‑3); submit → <strong>auto email giới thiệu dự án</strong> từ email dự án + <strong>lead đẩy về Google Spreadsheet</strong> thống kê (pha chuyển tiếp) → <strong>pha 2 đổ về CRM</strong> khi phần mềm tổng vận hành. <strong>Không live chat.</strong></td><td>Sheet 02 (A.6/A.8/A.12 — Comment An Phúc); <code>03</code> §2.3</td></tr><tr><td>BR‑18 🆕</td><td><strong>Đổi trạng thái hồ sơ 2 lớp (✅ AP chốt)</strong>: <code>STAFF</code> <strong>đề nghị</strong> (từ chối/cần bổ sung/duyệt online) → <code>ADMIN</code> <strong>duyệt sau cùng</strong>; lưu vết cả đề nghị lẫn quyết định. <code>DOC</code> (Sở Xây dựng) <strong>chỉ xem/theo dõi/giám sát</strong> — không có quyền thay đổi</td><td>Sheet 03 (bước 1 — Comment An Phúc); <code>04</code> §5 (BR‑NOXH‑07)</td></tr></tbody></table><hr><h2 id="_7-nguon-phap-ly-vien-dan-sheet-05-sheet-02-03" tabindex="-1">7. Nguồn pháp lý viện dẫn (Sheet 05 + Sheet 02/03) <a class="header-anchor" href="#_7-nguon-phap-ly-vien-dan-sheet-05-sheet-02-03" aria-label="Permalink to &quot;7. Nguồn pháp lý viện dẫn (Sheet 05 + Sheet 02/03)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Văn bản</th><th>Điều chỉnh</th></tr></thead><tbody><tr><td><strong>Nghị định 13/2023/NĐ‑CP</strong></td><td>Bảo vệ dữ liệu cá nhân (CCCD + hồ sơ tài chính = dữ liệu nhạy cảm; consent; DPIA nộp A05 trong 60 ngày; DPA)</td></tr><tr><td><strong>Luật Kinh doanh BĐS 2023</strong></td><td>Minh bạch thông tin, nhà ở HTTTL, đặt cọc ≤5%, bảo lãnh ngân hàng, cấm huy động vốn trái phép</td></tr><tr><td><strong>Luật Nhà ở 2023</strong></td><td>Xét duyệt NOXH đúng đối tượng/điều kiện</td></tr><tr><td><strong>Quy định đăng ký TMĐT — Bộ Công Thương</strong></td><td>Đăng ký online.gov.vn trước vận hành; công khai thông tin</td></tr><tr><td><strong>ATTT cấp độ 3</strong> (khung Nghị định 85/2016)</td><td>An toàn thông tin hệ thống — 🟡 sheet chưa chi tiết (OQ‑L8)</td></tr><tr><td><strong>Quyết định 856/QĐ‑UBND 22/06/2026</strong></td><td>Nguồn số liệu dự án (CĐT, quy mô, số tòa/căn, tiến độ khung 12/48 tháng)</td></tr></tbody></table><blockquote><p>Chi tiết phân định trách nhiệm AP ↔ MAYogu cho từng mục: <code>docs/06-legal.md</code>.</p></blockquote><hr><h2 id="_8-rang-buoc-gia-đinh-rui-ro" tabindex="-1">8. Ràng buộc, giả định &amp; rủi ro <a class="header-anchor" href="#_8-rang-buoc-gia-đinh-rui-ro" aria-label="Permalink to &quot;8. Ràng buộc, giả định &amp; rủi ro&quot;">​</a></h2><h3 id="_8-1-rang-buoc-constraints" tabindex="-1">8.1 Ràng buộc (constraints) <a class="header-anchor" href="#_8-1-rang-buoc-constraints" aria-label="Permalink to &quot;8.1 Ràng buộc (constraints)&quot;">​</a></h3><ul><li><strong>Pháp lý</strong>: toàn bộ mảng C/D phải tuân thủ NĐ 13/2023, Luật Nhà ở, Luật KDBĐS; đăng ký TMĐT trước vận hành; AI (nếu có) bắt buộc hạ tầng VN.</li><li><strong>Bố cục Web CĐT</strong>: theo template <strong>FIND</strong> (không redesign tự do).</li><li><strong>Sở hữu dữ liệu</strong>: AP sở hữu; MAYogu không khai thác (DPA/NDA).</li><li><strong>Không công bố số liệu chưa chính thức</strong>: giá bán, cơ cấu căn, diện tích còn chờ AP chốt.</li></ul><h3 id="_8-2-gia-đinh-assumptions-—-can-ap-xac-nhan-neu-sai-se-anh-huong-pham-vi" tabindex="-1">8.2 Giả định (assumptions) — cần AP xác nhận, nếu sai sẽ ảnh hưởng phạm vi <a class="header-anchor" href="#_8-2-gia-đinh-assumptions-—-can-ap-xac-nhan-neu-sai-se-anh-huong-pham-vi" aria-label="Permalink to &quot;8.2 Giả định (assumptions) — cần AP xác nhận, nếu sai sẽ ảnh hưởng phạm vi&quot;">​</a></h3><ul><li>A1: AP sẽ cung cấp <strong>bảng giá, cơ cấu căn, diện tích chính thức</strong> trước khi lên web (hiện chưa có — OQ‑N2/OQ‑D1).</li><li>A2: AP sẽ cung cấp <strong>media chất lượng thiết kế</strong> (logo gốc, render, mặt bằng CAD/PDF, video) — AP đã xác nhận <em>&quot;hình ảnh/video sẽ cung cấp sau&quot;</em> (10/2026), vẫn chờ (OQ‑8).</li><li>A3: <strong>Phần mềm kế toán</strong> để liên kết đã tồn tại và có cơ chế tích hợp (tên/cơ chế chưa nêu — OQ‑C1).</li><li>A4: AP chịu trách nhiệm <strong>nội dung pháp lý</strong> (luật sư soạn), MAYogu chỉ dựng giao diện (Sheet 05 mục 5).</li><li>A5: Tài khoản <strong>Sở Xây dựng</strong> sẽ được cấp quyền phù hợp — ✅ <strong>AP đã chốt: read‑only (xem/theo dõi/giám sát)</strong> (OQ‑6/OQ‑R1).</li><li>A6 🆕: <strong>Google Spreadsheet nhận lead</strong> do AP sở hữu/cấp quyền; giai đoạn chuyển tiếp trước khi CRM vận hành — cơ chế kỹ thuật + bảo mật chưa chốt (OQ‑10, OQ‑L10). Danh sách <strong>11 đối tượng / 3 trường hợp nhà ở / 3 trường hợp thu nhập</strong> sẽ được AP <em>&quot;chuẩn hoá sau&quot;</em> — form lead, tool kiểm tra điều kiện và F.A.12 dùng chung 1 nguồn.</li></ul><h3 id="_8-3-rui-ro-risks" tabindex="-1">8.3 Rủi ro (risks) <a class="header-anchor" href="#_8-3-rui-ro-risks" aria-label="Permalink to &quot;8.3 Rủi ro (risks)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Rủi ro</th><th>Hệ quả</th><th>Giảm thiểu (chỉ nêu, không bịa giải pháp kỹ thuật)</th></tr></thead><tbody><tr><td>R1</td><td>Nhiều bước NOXH còn <strong>&quot;check legal&quot;</strong> chưa xác nhận</td><td>Làm sai có thể vi phạm NĐ 13/2023</td><td>Pháp chế AP duyệt trước khi code (OQ‑N1)</td></tr><tr><td>R2</td><td><strong>Mâu thuẫn diện tích NOXH</strong> (36,8–76,9 vs ~25–77 m²)</td><td>Công bố sai thông tin dự án</td><td>AP chốt số chính thức (OQ‑D1)</td></tr><tr><td>R3</td><td><strong>Thiếu media/bảng giá</strong></td><td>Không hoàn thiện Web CĐT/NOTM</td><td>AP cung cấp (OQ‑8, OQ‑N2)</td></tr><tr><td>R4</td><td>Dùng <strong>AI</strong> không đúng ràng buộc VN</td><td>Vi phạm dữ liệu cá nhân</td><td>Chỉ dùng hạ tầng VN, AP đứng tên (BR‑13, OQ‑P1)</td></tr><tr><td>R5</td><td><strong>Mã nguồn hiện tại</strong> cài sản phẩm &quot;đấu giá&quot; cũ</td><td>Lệch hoàn toàn yêu cầu</td><td>Hạng mục rà soát code riêng (sau tài liệu)</td></tr><tr><td>R6</td><td><strong>ATTT cấp độ 3</strong> chưa rõ phạm vi</td><td>Thiếu hồ sơ an toàn hệ thống</td><td>Làm rõ với AP (OQ‑L8)</td></tr><tr><td>R7 🆕</td><td><strong>Lead (PII: họ tên, SĐT, email, hôn nhân, đối tượng chính sách, nhà ở, thu nhập) đổ về Google Spreadsheet</strong> theo yêu cầu mới của AP</td><td>Rủi ro NĐ 13/2023: bên xử lý thứ ba, khả năng <strong>chuyển dữ liệu xuyên biên giới</strong>, kiểm soát truy cập lỏng, chưa có DPIA/DPA cho kênh này</td><td>Pháp chế AP đánh giá <strong>trước khi bật form production</strong> (OQ‑L10); consent rõ ràng trên form (BR‑11); hạn chế quyền truy cập sheet; lộ trình chuyển về CRM (BR‑17)</td></tr><tr><td>R8 🆕</td><td>Sheet mới của AP (block <strong>TM1–TM8</strong>) có 2 chỗ <strong>nghi lỗi copy‑paste</strong> (&quot;nhà ở xã hội&quot; trong card TM; &quot;05 ảnh A1–A5&quot;)</td><td>Build sai nội dung công bố sản phẩm TM</td><td>AP xác nhận <strong>OQ‑D3</strong> trước khi build <code>03</code> §7b</td></tr></tbody></table><hr><h2 id="_9-khung-tien-đo-chi-dung-moc-sheet-neu-—-khong-suy-ra-ngay-mo-ban" tabindex="-1">9. Khung tiến độ (chỉ dùng mốc sheet nêu — không suy ra ngày mở bán) <a class="header-anchor" href="#_9-khung-tien-đo-chi-dung-moc-sheet-neu-—-khong-suy-ra-ngay-mo-ban" aria-label="Permalink to &quot;9. Khung tiến độ (chỉ dùng mốc sheet nêu — không suy ra ngày mở bán)&quot;">​</a></h2><p>Sheet <strong>không</strong> đưa lịch triển khai phần mềm cụ thể. Chỉ có hai loại mốc:</p><ol><li><strong>Khung pháp lý dự án (QĐ 856/QĐ‑UBND):</strong> khởi công <strong>tối đa 12 tháng</strong>, hoàn thành/nghiệm thu <strong>tối đa 48 tháng</strong> kể từ ngày chấp thuận chủ trương đầu tư đồng thời giao CĐT. → <strong>Không suy ra ngày mở bán.</strong></li><li><strong>Dòng thời gian một đợt tiếp nhận NOXH</strong> (Sheet 03 bước 4/14): X (kết thúc nhận hồ sơ mới) → X+5 (kết thúc bổ sung) → X+7 (kết thúc nộp bản gốc) → X+10 (trình Sở Xây dựng). Giá trị <strong>X thực tế</strong> do ADMIN thiết lập theo đợt (chưa có lịch — OQ‑N5).</li></ol><blockquote><p>🟡 <strong>OQ‑B2</strong>: Lịch triển khai phần mềm (thời điểm bàn giao từng mảng A–G, thứ tự ưu tiên, ngày go‑live web) <strong>chưa có trong sheet</strong> — cần AP × MAYogu thống nhất riêng. Tài liệu không tự đặt mốc.</p></blockquote><hr><h2 id="_10-tieu-chi-nghiem-thu-cap-cao-acceptance-o-muc-nghiep-vu" tabindex="-1">10. Tiêu chí nghiệm thu cấp cao (acceptance ở mức nghiệp vụ) <a class="header-anchor" href="#_10-tieu-chi-nghiem-thu-cap-cao-acceptance-o-muc-nghiep-vu" aria-label="Permalink to &quot;10. Tiêu chí nghiệm thu cấp cao (acceptance ở mức nghiệp vụ)&quot;">​</a></h2><blockquote><p>Mức chi tiết test case sẽ lập sau khi chốt open question. Ở mức BRD, nghiệm thu = đáp ứng đúng các yêu cầu sheet nêu:</p></blockquote><ul><li><strong>AC‑1</strong> (A/CRM): dữ liệu từ <strong>5 nguồn</strong> quy về <strong>1 ID khách duy nhất</strong>; xem được lịch sử trao đổi, tiến trình hồ sơ, tiến trình thanh toán, bản scan theo ID; <strong>chọn biểu mẫu → xuất ngay</strong>; ADMIN thêm được mẫu; nối kế toán cập nhật thanh toán/hoá đơn.</li><li><strong>AC‑2</strong> (C/NOXH): đi hết <strong>20 bước</strong>; <strong>state machine</strong> đúng; <strong>phân quyền</strong> đúng 5 vai trò — gồm <strong>cơ chế 2 lớp</strong> (STAFF đề nghị → ADMIN duyệt sau cùng) và <strong>DOC read‑only</strong> (BR‑18 ✅); khóa quyền sửa sau nộp; tiếp nhận theo đợt (X/X+5/X+7/X+10); bốc thăm lưu vết; chọn căn theo thứ tự công khai; <strong>2 tool tự kiểm tra</strong> (điều kiện + vay) đúng spec ✅ AP (<code>04</code> Bước 3); <strong>mã KH/mã hồ sơ</strong> đúng cấu trúc <code>AP‑APIM‑…</code> ✅.</li><li><strong>AC‑3</strong> (D/NOTM): đi hết <strong>8 bước</strong> (đăng ký → tư vấn → chốt căn → ký HĐ/đặt cọc → thanh toán → bàn giao); dữ liệu về CRM.</li><li><strong>AC‑4</strong> (B/Web CĐT): đúng <strong>bố cục FIND</strong>, thay nội dung/hình ảnh AP cung cấp; <strong>form lead 9 trường</strong> → auto email + Google Spreadsheet → CRM (BR‑17 ✅ — thay cho &quot;thu lead về CRM&quot; đơn tuyến); <strong>thêm nhóm sản phẩm TM1–TM8</strong> (<code>03</code> §7b — sau khi chốt OQ‑D3); số &quot;khoảng/dự kiến&quot; giữ nguyên.</li><li><strong>AC‑5</strong> (E/Legal): có <strong>DPIA</strong>, <strong>đăng ký TMĐT</strong>, <strong>DPA/NDA</strong>, giao diện <strong>opt‑in bắt buộc</strong>; nếu AI thì <strong>hạ tầng VN</strong>.</li><li><strong>AC‑6</strong> (F/G): <strong>12 ấn phẩm</strong> đúng quy cách (F); <strong>kênh online + luồng lead về CRM</strong> (G).</li></ul><hr><h2 id="_11-cau-hoi-mo-đay-ve-docs-09" tabindex="-1">11. Câu hỏi mở (đẩy về <code>docs/09</code>) <a class="header-anchor" href="#_11-cau-hoi-mo-đay-ve-docs-09" aria-label="Permalink to &quot;11. Câu hỏi mở (đẩy về `docs/09`)&quot;">​</a></h2><p>BRD kế thừa toàn bộ câu hỏi mở của các doc mảng. Các câu hỏi <strong>cấp danh mục</strong> phát sinh từ doc này:</p><table tabindex="0"><thead><tr><th>ID</th><th>Nội dung</th><th>Mức</th></tr></thead><tbody><tr><td>OQ‑B1</td><td>AP có muốn đặt <strong>KPI số</strong> (doanh số/lead/chuyển đổi) không? Sheet không nêu</td><td>🟡</td></tr><tr><td>OQ‑B2</td><td><strong>Lịch triển khai phần mềm</strong> (bàn giao từng mảng, ưu tiên, go‑live)</td><td>🟡</td></tr></tbody></table><p>Toàn bộ câu hỏi còn lại (OQ‑1…8, OQ‑C…, OQ‑N…, OQ‑L…, OQ‑P…, OQ‑D…) tổng hợp tại <strong><code>docs/09-open-questions.md</code></strong>.</p><hr><h2 id="_12-tham-chieu" tabindex="-1">12. Tham chiếu <a class="header-anchor" href="#_12-tham-chieu" aria-label="Permalink to &quot;12. Tham chiếu&quot;">​</a></h2><ul><li><code>docs/00-project-context.md</code> — bối cảnh, mô hình 5 nguồn, quy ước ID/vai trò, glossary.</li><li><code>docs/02</code>–<code>docs/08</code> — đặc tả chi tiết từng mảng A–G.</li><li><code>docs/06-legal.md</code> — ràng buộc pháp lý &amp; phân định trách nhiệm.</li><li><code>docs/09-open-questions.md</code> — tổng hợp câu hỏi mở.</li><li><code>docs/_archive/README.md</code> — bộ doc cũ (sàn đấu giá) không bám yêu cầu, đã lưu trữ.</li></ul>',63)])])}const m=n(r,[["render",c]]);export{l as __pageData,m as default};
